import os
import sys
import json
import time
import random
import hashlib
import pathlib
import mimetypes
import urllib.request
import urllib.error
import urllib.parse
import socket
import re

DEFAULT_BASE_URL = ""
DEFAULT_MODEL = "grok-4-fast-reasoning"
DEFAULT_TIMEOUT_SECONDS = 3600
DEFAULT_TEMPERATURE = 0.2

DEFAULT_PREVIEW_MAX_BYTES = 220000
DEFAULT_PREVIEW_HEAD_BYTES = 110000
DEFAULT_PREVIEW_TAIL_BYTES = 110000

DEFAULT_OVERVIEW_TARGET_CHARS = 30 * 1024
DEFAULT_OVERVIEW_MIN_CHARS = 28 * 1024
DEFAULT_OVERVIEW_MAX_CHARS = 32 * 1024

DEFAULT_PER_FILE_SENTENCES = 12

DEFAULT_OUT_DIRNAME = "ai_docs"
DEFAULT_FILE_DESCRIPTIONS_NAME = "file_descriptions.txt"
DEFAULT_APP_OVERVIEW_NAME = "app_overview.txt"
DEFAULT_STATE_JSON_NAME = "state.json"

DEFAULT_MAX_REQUEST_RETRIES = 8
DEFAULT_RETRY_BASE_DELAY_SECONDS = 1.25
DEFAULT_RETRY_MAX_DELAY_SECONDS = 30.0

BINARY_NULL_BYTE = b"\x00"

SENTENCE_SPLIT_RE = re.compile(r"(?<=[.!?])\s+")
TRIM_WHITESPACE_RE = re.compile(r"[ \t]+")


def _env_bool(name: str, default: bool = False) -> bool:
    v = os.getenv(name)
    if v is None:
        return default
    v = v.strip().lower()
    return v in ("1", "true", "yes", "y", "on")


def _env_int(name: str, default: int) -> int:
    v = os.getenv(name)
    if v is None or not v.strip():
        return default
    try:
        return int(v.strip())
    except Exception:
        return default


def _env_float(name: str, default: float) -> float:
    v = os.getenv(name)
    if v is None or not v.strip():
        return default
    try:
        return float(v.strip())
    except Exception:
        return default


def _safe_relpath(path: pathlib.Path, root: pathlib.Path) -> str:
    try:
        return str(path.relative_to(root))
    except Exception:
        return str(path)


def _is_probably_binary(sample: bytes) -> bool:
    if not sample:
        return False
    if BINARY_NULL_BYTE in sample:
        return True
    nontext = 0
    for b in sample[:4096]:
        if b in (9, 10, 13):
            continue
        if 32 <= b <= 126:
            continue
        if b >= 128:
            continue
        nontext += 1
    return nontext > 16


def _sha256_file(path: pathlib.Path, chunk_size: int = 1024 * 1024) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def _read_preview_bytes(path: pathlib.Path, max_bytes: int, head_bytes: int, tail_bytes: int) -> tuple[bytes, bool, bool]:
    size = path.stat().st_size
    with path.open("rb") as f:
        head = f.read(min(head_bytes, max_bytes, size))
        if size <= max_bytes:
            return head, False, False
        tail_len = min(tail_bytes, max_bytes - len(head), size - len(head))
        if tail_len <= 0:
            return head, True, False
        try:
            f.seek(max(0, size - tail_len))
        except Exception:
            return head, True, False
        tail = f.read(tail_len)
        combined = head + b"\n\n--- FILE TAIL PREVIEW ---\n\n" + tail
        return combined, True, False


def _decode_text(data: bytes) -> str:
    try:
        return data.decode("utf-8")
    except Exception:
        try:
            return data.decode("utf-8", errors="replace")
        except Exception:
            try:
                return data.decode("latin-1", errors="replace")
            except Exception:
                return ""


def _normalize_text_for_prompt(s: str) -> str:
    s = s.replace("\r\n", "\n").replace("\r", "\n")
    lines = s.split("\n")
    lines = [line.rstrip() for line in lines]
    s = "\n".join(lines)
    s = TRIM_WHITESPACE_RE.sub(" ", s)
    return s


class XAIClient:
    def __init__(self, api_key: str, base_url: str = DEFAULT_BASE_URL, timeout_seconds: int = DEFAULT_TIMEOUT_SECONDS):
        if not api_key or not api_key.strip():
            raise ValueError("Missing XAI_API_KEY environment variable.")
        self.api_key = api_key.strip()
        self.base_url = base_url.rstrip("/")
        self.timeout_seconds = int(timeout_seconds)

    def _request(self, method: str, path: str, body: dict | None = None) -> dict:
        url = self.base_url + path
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Accept": "application/json",
        }
        data = None
        if body is not None:
            payload = json.dumps(body, ensure_ascii=False).encode("utf-8")
            data = payload
            headers["Content-Type"] = "application/json"

        last_err = None
        for attempt in range(DEFAULT_MAX_REQUEST_RETRIES):
            try:
                req = urllib.request.Request(url=url, data=data, headers=headers, method=method.upper())
                with urllib.request.urlopen(req, timeout=self.timeout_seconds) as resp:
                    raw = resp.read()
                    if not raw:
                        return {}
                    try:
                        return json.loads(raw.decode("utf-8"))
                    except Exception:
                        return json.loads(raw.decode("utf-8", errors="replace"))
            except urllib.error.HTTPError as e:
                try:
                    err_body = e.read()
                except Exception:
                    err_body = b""
                status = getattr(e, "code", None)
                retry_after = None
                try:
                    retry_after = e.headers.get("Retry-After")
                except Exception:
                    retry_after = None
                retriable = status in (408, 409, 425, 429, 500, 502, 503, 504)
                last_err = (status, err_body)
                if not retriable or attempt >= DEFAULT_MAX_REQUEST_RETRIES - 1:
                    msg = ""
                    if err_body:
                        try:
                            msg = err_body.decode("utf-8", errors="replace")
                        except Exception:
                            msg = repr(err_body)
                    raise RuntimeError(f"HTTP error {status} for {url}: {msg}") from e
                delay = self._compute_backoff(attempt, retry_after)
                time.sleep(delay)
            except (urllib.error.URLError, socket.timeout, TimeoutError) as e:
                last_err = e
                if attempt >= DEFAULT_MAX_REQUEST_RETRIES - 1:
                    raise RuntimeError(f"Network error for {url}: {e}") from e
                delay = self._compute_backoff(attempt, None)
                time.sleep(delay)

        raise RuntimeError(f"Request failed for {url}: {last_err}")

    def _compute_backoff(self, attempt: int, retry_after: str | None) -> float:
        if retry_after:
            try:
                v = float(str(retry_after).strip())
                if v >= 0:
                    return min(DEFAULT_RETRY_MAX_DELAY_SECONDS, v + random.random())
            except Exception:
                pass
        base = DEFAULT_RETRY_BASE_DELAY_SECONDS * (2 ** attempt)
        jitter = random.random() * 0.75 + 0.25
        delay = base * jitter
        return min(DEFAULT_RETRY_MAX_DELAY_SECONDS, delay)

    def list_models(self) -> list[str]:
        data = self._request("GET", "/v1/models", None)
        out = []
        if isinstance(data, dict) and "data" in data and isinstance(data["data"], list):
            for item in data["data"]:
                if isinstance(item, dict) and "id" in item:
                    mid = str(item["id"])
                    out.append(mid)
        elif isinstance(data, dict) and "models" in data and isinstance(data["models"], list):
            for item in data["models"]:
                if isinstance(item, dict) and "id" in item:
                    out.append(str(item["id"]))
        return out

    def chat_completions(self, model: str, messages: list[dict], temperature: float = DEFAULT_TEMPERATURE, max_tokens: int | None = None) -> str:
        body = {
            "model": model,
            "messages": messages,
            "temperature": float(temperature),
        }
        if max_tokens is not None:
            body["max_tokens"] = int(max_tokens)
        data = self._request("POST", "/v1/chat/completions", body)
        if not isinstance(data, dict):
            raise RuntimeError("Invalid response type from API.")
        if "choices" in data and isinstance(data["choices"], list) and data["choices"]:
            choice0 = data["choices"][0]
            if isinstance(choice0, dict):
                msg = choice0.get("message")
                if isinstance(msg, dict):
                    content = msg.get("content")
                    if isinstance(content, str):
                        return content
        if "output" in data and isinstance(data["output"], list):
            text_parts = []
            for item in data["output"]:
                if isinstance(item, dict):
                    content = item.get("content")
                    if isinstance(content, list):
                        for seg in content:
                            if isinstance(seg, dict) and seg.get("type") == "output_text" and isinstance(seg.get("text"), str):
                                text_parts.append(seg["text"])
            if text_parts:
                return "\n".join(text_parts)
        raise RuntimeError(f"Could not extract assistant text from API response: {json.dumps(data, ensure_ascii=False)[:4000]}")


def choose_model(client: XAIClient, requested: str) -> str:
    requested = (requested or "").strip() or DEFAULT_MODEL
    requested = requested.strip()
    allow_fallback = not _env_bool("XAI_NO_MODEL_FALLBACK", False)
    if not allow_fallback:
        return requested
    try:
        mids = set(client.list_models())
    except Exception:
        return requested
    candidates = []
    candidates.append(requested)
    if "4.1" in requested:
        candidates.append(requested.replace("4.1", "4"))
    candidates.extend([
        "grok-4-fast-reasoning",
        "grok-4",
        "grok-4-latest",
        "grok-4-fast-non-reasoning",
        "grok-code-fast-1",
    ])
    seen = set()
    for c in candidates:
        c = (c or "").strip()
        if not c or c in seen:
            continue
        seen.add(c)
        if c in mids:
            return c
    return requested


def iter_project_files(root: pathlib.Path, exclude_dirnames: set[str], exclude_paths: set[pathlib.Path]) -> list[pathlib.Path]:
    files = []
    for dirpath, dirnames, filenames in os.walk(root, topdown=True, followlinks=False):
        dp = pathlib.Path(dirpath)
        filtered_dirnames = []
        for d in dirnames:
            if d in exclude_dirnames:
                continue
            candidate = dp / d
            skip = False
            for ep in exclude_paths:
                try:
                    candidate.relative_to(ep)
                    skip = True
                    break
                except Exception:
                    continue
            if not skip:
                filtered_dirnames.append(d)
        dirnames[:] = filtered_dirnames
        for fn in filenames:
            p = dp / fn
            if not p.is_file():
                continue
            skip = False
            for ep in exclude_paths:
                try:
                    p.relative_to(ep)
                    skip = True
                    break
                except Exception:
                    continue
            if skip:
                continue
            files.append(p)
    files.sort(key=lambda x: str(x).lower())
    return files


def build_file_record(root: pathlib.Path, path: pathlib.Path, preview_max_bytes: int, preview_head_bytes: int, preview_tail_bytes: int) -> dict:
    rel = _safe_relpath(path, root)
    st = path.stat()
    size = int(st.st_size)
    mtime = float(st.st_mtime)
    mime, _ = mimetypes.guess_type(str(path))
    mime = mime or "application/octet-stream"
    sha = ""
    sha_err = None
    try:
        sha = _sha256_file(path)
    except Exception as e:
        sha_err = str(e)

    sample = b""
    is_binary = False
    is_truncated = False
    preview_text = ""
    preview_hex = ""
    preview_err = None
    try:
        with path.open("rb") as f:
            sample = f.read(8192)
        is_binary = _is_probably_binary(sample)
        if is_binary:
            head = sample[:512]
            preview_hex = head.hex()
            is_truncated = size > len(sample)
        else:
            raw, truncated_flag, _ = _read_preview_bytes(path, preview_max_bytes, preview_head_bytes, preview_tail_bytes)
            is_truncated = truncated_flag
            preview_text = _normalize_text_for_prompt(_decode_text(raw))
    except Exception as e:
        preview_err = str(e)

    record = {
        "path": rel,
        "abs_path": str(path),
        "size_bytes": size,
        "mtime_epoch": mtime,
        "mime": mime,
        "sha256": sha,
        "sha256_error": sha_err,
        "is_binary": bool(is_binary),
        "is_truncated_preview": bool(is_truncated),
        "preview_text": preview_text,
        "preview_hex": preview_hex,
        "preview_error": preview_err,
    }
    return record


def _sentence_count(text: str) -> int:
    t = text.strip()
    if not t:
        return 0
    parts = SENTENCE_SPLIT_RE.split(t)
    parts = [p.strip() for p in parts if p.strip()]
    return len(parts)


def _clean_model_text(text: str) -> str:
    t = text.replace("\r\n", "\n").replace("\r", "\n").strip()
    t = re.sub(r"\n{3,}", "\n\n", t)
    return t


def summarize_one_file(client: XAIClient, model: str, record: dict, per_file_sentences: int) -> str:
    path = record.get("path", "")
    size_bytes = record.get("size_bytes", 0)
    mime = record.get("mime", "")
    sha = record.get("sha256", "")
    sha_err = record.get("sha256_error", None)
    is_binary = bool(record.get("is_binary", False))
    is_trunc = bool(record.get("is_truncated_preview", False))
    preview_err = record.get("preview_error", None)
    preview_text = record.get("preview_text", "")
    preview_hex = record.get("preview_hex", "")

    sys_msg = {
        "role": "system",
        "content": (
            "You are an expert software analyst. "
            "Write clear, concrete, production-oriented descriptions. "
            "Return exactly "
            + str(per_file_sentences)
            + " sentences, no bullet points, no numbering, no headings. "
            "Each sentence must end with a period."
        ),
    }

    meta_lines = [
        f"File path: {path}",
        f"Size (bytes): {size_bytes}",
        f"MIME: {mime}",
        f"SHA-256: {sha if sha else ''}",
        f"SHA-256 error: {sha_err if sha_err else ''}",
        f"Binary: {is_binary}",
        f"Preview truncated: {is_trunc}",
        f"Preview read error: {preview_err if preview_err else ''}",
    ]
    meta_block = "\n".join(meta_lines)

    if is_binary:
        content_block = "Binary/opaque content. First 512 bytes as hex:\n" + (preview_hex or "")
    else:
        content_block = "Text preview:\n" + (preview_text or "")

    user_msg = {
        "role": "user",
        "content": (
            "Describe this file's purpose and behavior, key functions/classes, important inputs/outputs, "
            "and how it likely fits into the app. "
            "If content is missing or truncated, infer carefully from what is present.\n\n"
            + meta_block
            + "\n\n"
            + content_block
        ),
    }

    raw = client.chat_completions(model=model, messages=[sys_msg, user_msg], temperature=_env_float("XAI_TEMPERATURE", DEFAULT_TEMPERATURE))
    cleaned = _clean_model_text(raw)

    if _sentence_count(cleaned) != per_file_sentences:
        fix_sys = {
            "role": "system",
            "content": (
                "Rewrite the text to satisfy formatting constraints. "
                "Return exactly "
                + str(per_file_sentences)
                + " sentences, no bullet points, no numbering, no headings. "
                "Each sentence must end with a period."
            ),
        }
        fix_user = {
            "role": "user",
            "content": "Rewrite the following so it is exactly the required number of sentences:\n\n" + cleaned,
        }
        fixed = client.chat_completions(model=model, messages=[fix_sys, fix_user], temperature=0.0)
        cleaned = _clean_model_text(fixed)

    return cleaned


def build_app_overview(client: XAIClient, model: str, file_summaries: list[dict], target_chars: int, min_chars: int, max_chars: int) -> str:
    summaries_text_parts = []
    for item in file_summaries:
        p = item.get("path", "")
        s = item.get("summary", "")
        summaries_text_parts.append(f"FILE: {p}\n{s}\n")
    summaries_block = "\n".join(summaries_text_parts)

    sys_msg = {
        "role": "system",
        "content": (
            "You are an expert software architect and technical writer. "
            "Write a detailed, practical overview of the entire application based on file summaries. "
            "Use plain text paragraphs with short section titles inline if helpful, but no markdown. "
            "Do not include bullet points or numbering. "
            "Target approximately "
            + str(target_chars)
            + " characters. "
            "Focus on what the app is, how it works end-to-end, major modules, data flow, configuration, external services, and likely runtime behavior."
        ),
    }
    user_msg = {
        "role": "user",
        "content": (
            "Create a full app description from these file summaries.\n\n"
            "Hard constraints:\n"
            f"- Output length between {min_chars} and {max_chars} characters.\n"
            "- Plain text only.\n"
            "- No bullet points, no numbering.\n\n"
            "File summaries:\n\n"
            + summaries_block
        ),
    }

    text = _clean_model_text(client.chat_completions(model=model, messages=[sys_msg, user_msg], temperature=_env_float("XAI_TEMPERATURE", DEFAULT_TEMPERATURE)))
    if not (min_chars <= len(text) <= max_chars):
        tighten_sys = {
            "role": "system",
            "content": (
                "You rewrite text to meet a strict character-length constraint while preserving meaning. "
                "Return plain text only, no bullet points, no numbering."
            ),
        }
        tighten_user = {
            "role": "user",
            "content": (
                f"Rewrite the following to be between {min_chars} and {max_chars} characters, preserving as much detail as possible:\n\n"
                + text
            ),
        }
        text = _clean_model_text(client.chat_completions(model=model, messages=[tighten_sys, tighten_user], temperature=0.0))
        if len(text) > max_chars:
            text = text[:max_chars].rstrip()
        if len(text) < min_chars:
            pad_sys = {
                "role": "system",
                "content": (
                    "You expand text carefully with concrete technical detail consistent with the provided content. "
                    "Return plain text only, no bullet points, no numbering."
                ),
            }
            pad_user = {
                "role": "user",
                "content": (
                    f"Expand the following to be between {min_chars} and {max_chars} characters without inventing contradictions; add plausible missing technical detail consistent with the summaries:\n\n"
                    + text
                ),
            }
            text = _clean_model_text(client.chat_completions(model=model, messages=[pad_sys, pad_user], temperature=0.2))
            if len(text) > max_chars:
                text = text[:max_chars].rstrip()
    return text


def _load_state(path: pathlib.Path) -> dict:
    if not path.exists():
        return {}
    try:
        raw = path.read_text("utf-8")
    except Exception:
        try:
            raw = path.read_text("utf-8", errors="replace")
        except Exception:
            return {}
    try:
        data = json.loads(raw)
        if isinstance(data, dict):
            return data
    except Exception:
        return {}
    return {}


def _save_state(path: pathlib.Path, data: dict) -> None:
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    tmp.replace(path)


def main() -> int:
    root = pathlib.Path(os.getcwd()).resolve()

    api_key = os.getenv("XAI_API_KEY", "").strip()
    base_url = os.getenv("XAI_BASE_URL", DEFAULT_BASE_URL).strip() or DEFAULT_BASE_URL
    requested_model = os.getenv("XAI_MODEL", DEFAULT_MODEL).strip() or DEFAULT_MODEL
    timeout_seconds = _env_int("XAI_TIMEOUT_SECONDS", DEFAULT_TIMEOUT_SECONDS)

    per_file_sentences = _env_int("PER_FILE_SENTENCES", DEFAULT_PER_FILE_SENTENCES)
    if per_file_sentences < 10:
        per_file_sentences = 10
    if per_file_sentences > 15:
        per_file_sentences = 15

    preview_max_bytes = _env_int("PREVIEW_MAX_BYTES", DEFAULT_PREVIEW_MAX_BYTES)
    preview_head_bytes = _env_int("PREVIEW_HEAD_BYTES", DEFAULT_PREVIEW_HEAD_BYTES)
    preview_tail_bytes = _env_int("PREVIEW_TAIL_BYTES", DEFAULT_PREVIEW_TAIL_BYTES)

    out_dirname = os.getenv("OUT_DIR", DEFAULT_OUT_DIRNAME).strip() or DEFAULT_OUT_DIRNAME
    out_dir = (root / out_dirname).resolve()
    out_dir.mkdir(parents=True, exist_ok=True)

    file_desc_path = (out_dir / DEFAULT_FILE_DESCRIPTIONS_NAME).resolve()
    app_overview_path = (out_dir / DEFAULT_APP_OVERVIEW_NAME).resolve()
    state_path = (out_dir / DEFAULT_STATE_JSON_NAME).resolve()

    exclude_dirnames = set()
    exclude_dirnames.add(out_dir.name)

    exclude_paths = {out_dir, file_desc_path, app_overview_path, state_path}

    client = XAIClient(api_key=api_key, base_url=base_url, timeout_seconds=timeout_seconds)
    model = choose_model(client, requested_model)

    state = _load_state(state_path)
    done = state.get("done", {})
    if not isinstance(done, dict):
        done = {}

    all_files = iter_project_files(root=root, exclude_dirnames=exclude_dirnames, exclude_paths=exclude_paths)
    if not all_files:
        (out_dir / DEFAULT_FILE_DESCRIPTIONS_NAME).write_text("No files found.\n", encoding="utf-8")
        (out_dir / DEFAULT_APP_OVERVIEW_NAME).write_text("No files found to describe.\n", encoding="utf-8")
        _save_state(state_path, {"done": {}, "model": model, "base_url": base_url, "root": str(root)})
        return 0

    file_summaries = []
    total = len(all_files)

    resume = _env_bool("RESUME", True)
    force = _env_bool("FORCE", False)

    for idx, path in enumerate(all_files, start=1):
        rel = _safe_relpath(path, root)
        key = rel
        if not force and resume and key in done and isinstance(done[key], dict) and "summary" in done[key]:
            summary = str(done[key].get("summary", "")).strip()
            if summary:
                file_summaries.append({"path": rel, "summary": summary})
                sys.stdout.write(f"[{idx}/{total}] SKIP {rel}\n")
                sys.stdout.flush()
                continue

        sys.stdout.write(f"[{idx}/{total}] SUMMARIZE {rel}\n")
        sys.stdout.flush()

        record = build_file_record(
            root=root,
            path=path,
            preview_max_bytes=preview_max_bytes,
            preview_head_bytes=preview_head_bytes,
            preview_tail_bytes=preview_tail_bytes,
        )

        try:
            summary = summarize_one_file(client=client, model=model, record=record, per_file_sentences=per_file_sentences)
        except Exception as e:
            summary = (
                f"Could not summarize this file due to an error. "
                f"The file exists at path {rel}. "
                f"The error encountered was: {str(e)}. "
                f"Manual inspection is recommended to understand its contents and purpose."
            )
            if _sentence_count(summary) < 10:
                summary = summary + " This file may still be important for the application. Please review it directly."

        file_summaries.append({"path": rel, "summary": summary})
        done[key] = {"summary": summary, "sha256": record.get("sha256", ""), "size_bytes": record.get("size_bytes", 0), "mtime_epoch": record.get("mtime_epoch", 0)}
        _save_state(state_path, {"done": done, "model": model, "base_url": base_url, "root": str(root)})

    lines = []
    lines.append(f"Model: {model}")
    lines.append(f"Base URL: {base_url}")
    lines.append(f"Root: {str(root)}")
    lines.append("")
    for item in file_summaries:
        p = item["path"]
        s = _clean_model_text(item["summary"])
        lines.append("==== FILE BEGIN ====")
        lines.append(f"PATH: {p}")
        lines.append(s)
        lines.append("==== FILE END ====")
        lines.append("")
    file_desc_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")

    target_chars = _env_int("OVERVIEW_TARGET_CHARS", DEFAULT_OVERVIEW_TARGET_CHARS)
    min_chars = _env_int("OVERVIEW_MIN_CHARS", DEFAULT_OVERVIEW_MIN_CHARS)
    max_chars = _env_int("OVERVIEW_MAX_CHARS", DEFAULT_OVERVIEW_MAX_CHARS)
    if min_chars < 1000:
        min_chars = 1000
    if max_chars <= min_chars:
        max_chars = min_chars + 2000

    sys.stdout.write("BUILD OVERVIEW\n")
    sys.stdout.flush()

    overview = build_app_overview(
        client=client,
        model=model,
        file_summaries=file_summaries,
        target_chars=target_chars,
        min_chars=min_chars,
        max_chars=max_chars,
    )
    app_overview_path.write_text(overview.strip() + "\n", encoding="utf-8")

    _save_state(state_path, {"done": done, "model": model, "base_url": base_url, "root": str(root)})

    sys.stdout.write(f"DONE\nWROTE: {str(file_desc_path)}\nWROTE: {str(app_overview_path)}\n")
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
